ACT['fo-save'] = f => { const Fx = S.formations[f.dataset.f]; Fx.name = $('#fo-n').value; Fx.price = +$('#fo-p').value; Fx.pitch = $('#fo-pitch').value; Fx.trainer = $('#fo-tr').value; Fx.levels = $('#fo-lv').value.split(',').map(x=>x.trim()).filter(Boolean);
  const lines = $('#fo-m').value.split('\n').map(x=>x.trim()).filter(Boolean); lines.forEach((l,i) => { if (Fx.prog[i]) Fx.prog[i].t = l; else Fx.prog.push({n:i+1, t:l, d:Fx.prog[Fx.prog.length-1].d+7, hl:Fx.prog[0].hl, mode:'Présentiel', done:false}); }); Fx.prog.length = Math.max(lines.length, Fx.prog.filter(x=>x.done).length); S.st && S.st.seances.filter(x=>x.f===f.dataset.f).forEach(x=>{ const pp = Fx.prog[x.n-1]; if (pp) x.t = pp.t; }); F[f.dataset.f].price = Fx.price; audit('Formation modifiée', Fx.name); closeModal(); rerender(); toast('Formation mise à jour. Les espaces étudiants reflètent les changements.'); };
