function conflicts(){ const out = []; S.planning.forEach((a,i)=>S.planning.slice(i+1).forEach(b=>{ if (a.day===b.day && a.h===b.h) { if (a.trainer===b.trainer) out.push({a,b,why:`${a.trainer} est planifié deux fois`}); else if (a.room===b.room && a.room!=='En ligne') out.push({a,b,why:`${a.room} est réservée deux fois`}); } })); return out; }
view('a-sessions','admin','Sessions et promotions','fa-calendar-days', () => { const cf = conflicts();
  return `<div class="d-flex justify-content-end mb-3"><button class="btn btn-primary" data-act="se-new"><i class="fa-solid fa-plus me-1"></i>Nouvelle session</button></div>
  <div class="panel tbl mb-3"><table class="table"><thead><tr><th>Session</th><th>Dates</th><th style="min-width:150px">Capacité</th><th>Niveaux</th><th>Lieux</th><th>Statut</th><th></th></tr></thead><tbody>${S.sessions.map(s=>`<tr><td><b>${s.name}</b><div class="mono small muted">${s.id}</div></td><td class="small num">${s.start} → ${s.end}</td><td>${bar(s.enrolled/s.cap*100)}<span class="small num muted">${s.enrolled} / ${s.cap}</span></td><td class="small">${s.groups.join(' · ')}</td><td class="small">${s.place}</td><td>${pill(s.status, s.status==='Active'?'ok':s.status==='Planifiée'?'info':'mute')}</td><td class="text-end"><button class="btn btn-ghost btn-sm" data-act="se-assign" data-id="${s.id}">Affecter</button></td></tr>`).join('')}</tbody></table></div>
  ${panel('Conflits de planification', cf.length ? cf.map((c,i)=>`<div class="alert-strip as-bad mb-2 flex-wrap"><i class="fa-solid fa-triangle-exclamation"></i><div style="flex:1;min-width:220px"><b>${c.why}</b> le ${c.a.day.split('-').reverse().join('/')} à ${c.a.h}h00<div class="small">${esc(c.a.t)} (${c.a.g}) et ${esc(c.b.t)} (${c.b.g})</div></div><button class="btn btn-ghost btn-sm" data-act="cf-fix" data-id="${c.b.id}">Décaler « ${esc(c.b.g)} » à 14h00</button></div>`).join('') : `<div class="alert-strip as-ok"><i class="fa-solid fa-circle-check"></i>Aucun conflit détecté sur les 2 prochaines semaines.</div>`, {sub:'salles et formateurs'})}`; });
ACT['cf-fix'] = el => { const p = S.planning.find(x=>x.id===el.dataset.id); p.h = 14; audit('Séance replanifiée', `${p.t} → 14h00`); rerender(); toast('Séance décalée. Les étudiants concernés sont notifiés.'); };
