view('a-travaux','admin','Travaux et validations','fa-clipboard-check', () => { S.aw = S.aw || [{f:'DG',t:'Affiche — Festival Abidjan Urban Arts',type:'Travail pratique',aff:'Collectif · Débutant',due:'30/10/2026',sub:8,tot:12,pend:5,ob:true},{f:'DG',t:'Logo — maquis',type:'Projet graphique',aff:'Collectif · tous DG',due:'25/10/2026',sub:15,tot:16,pend:6,ob:true},{f:'CM',t:'Calendrier éditorial — novembre',type:'Livrable',aff:'Collectif · G2',due:'24/10/2026',sub:6,tot:14,pend:4,ob:true},{f:'GIA',t:'Tableau de gestion des stocks',type:'Travail pratique',aff:'Collectif · Avancé',due:'23/10/2026',sub:11,tot:13,pend:3,ob:true},{f:'GIA',t:'Exercice Excel — rattrapage',type:'Exercice',aff:'Individuel · Nadia Touré',due:'28/10/2026',sub:0,tot:1,pend:0,ob:false}];
  const tab = atabs('atw',[['val',`À valider${toValidate().length?` (${toValidate().length})`:''}`],['tr','Travaux'],['ev','QCM et examens'],['hist','Historique']]);
  if (S.ui.atw==='val') return tab + validationTab();
  if (S.ui.atw==='tr') return tab + `<div class="d-flex justify-content-end mb-3"><button class="btn btn-primary" data-act="aw-new"><i class="fa-solid fa-plus me-1"></i>Attribuer un projet</button></div><div class="panel tbl"><table class="table"><thead><tr><th>Projet</th><th>Attribué à</th><th>À rendre</th><th class="text-end">Démarrés</th><th style="min-width:150px">Publiés</th><th class="text-end">À valider</th><th></th></tr></thead><tbody>${S.aw.map((w,i)=>`<tr class="clickable" data-act="aw-track" data-i="${i}"><td>${fchip(w.f)} <b class="small">${esc(w.t)}</b>${w.ob?' <span class="fchip p-mute">Obligatoire</span>':''}</td><td class="small">${w.aff}</td><td class="num small">${w.due}</td><td class="text-end num small">${w.start ?? Math.min(w.tot, w.sub+2)} / ${w.tot}</td><td>${bar(w.tot?w.sub/w.tot*100:0,w.f)}<span class="small num muted">${w.sub} / ${w.tot}</span></td><td class="text-end num">${w.pend}</td><td><i class="fa-solid fa-chevron-right muted"></i></td></tr>`).join('')}</tbody></table></div>`;
  if (S.ui.atw==='ev') return tab + `<div class="panel tbl"><table class="table"><thead><tr><th>Évaluation</th><th>Type</th><th>Date</th><th class="text-end">Copies</th><th class="text-end">Réussite</th><th>Résultats</th></tr></thead><tbody>${[['DG','QCM — Photoshop','QCM','02/10',24,'14,8','92 %','Publiés'],['DG','Examen — Illustrator','Examen','10/10',24,'13,2','83 %','Publiés'],['CM','QCM — Stratégie digitale','QCM','07/10',18,'12,6','78 %','Publiés'],['CM','Étude de cas — Personas','Examen','16/10',17,'—','—','En correction'],['GIA','Examen pratique — Excel','Examen','13/10',21,'14,1','90 %','Publiés'],['GIA','QCM — Google Workspace','QCM','22/10',0,'—','—','Ouvert']].map(e=>`<tr><td>${fchip(e[0])} <b class="small">${e[1]}</b></td><td class="small">${e[2]}</td><td class="num small">${e[3]}/2026</td><td class="text-end num">${e[4]}</td><td class="text-end num">${e[6]}</td><td>${pill(e[7], e[7]==='Publiés'?'ok':e[7]==='Ouvert'?'acc':'warn')}</td></tr>`).join('')}</tbody></table></div>`;
  return tab + `<div class="panel tbl"><table class="table"><thead><tr><th>Date</th><th>Correcteur</th><th>Travail</th><th>Étudiant</th><th>Décision</th></tr></thead><tbody>${S.audit.filter(a=>['Travail corrigé','Travail validé','Travail à reprendre'].includes(a.a)).concat([{d:'20/10/2026 17:40',u:'Koffi Brou',o:'Lettre de motivation — Word — Aya Kouassi — Validé'},{d:'19/10/2026 11:02',u:'Fatim Diabaté',o:'Personas — marque de jus locale — Kevin Ahoua — À reprendre'}]).map(a=>{ const p = a.o.split(' — '); return `<tr><td class="num small">${a.d}</td><td class="small">${a.u}</td><td class="small">${esc(p.slice(0,-2).join(' — ')||p[0])}</td><td class="small">${esc(p[p.length-2]||'')}</td><td>${pill(p[p.length-1]||'—', (p[p.length-1]||'').includes('Valid')?'ok':'bad')}</td></tr>`; }).join('')}</tbody></table></div>`; });
/* ----- Attribuer un projet à toute une formation ou à des étudiants précis ----- */
const awPool = f => S.students.filter(s=>s.status==='Actif' && s.f.includes(f));
function awListHTML(){ const f = $('#aw-f')?.value || 'DG', sel = S.ui.awSel || [];
  return awPool(f).map(s=>`<label class="cm-row"><input class="form-check-input" type="checkbox" data-chg="aw-sel" value="${s.id}" ${sel.includes(s.id)?'checked':''}>${avatar(s.name,'sm')}<span class="ri-main"><span class="d-block small fw-semibold">${esc(s.name)}</span><span class="d-block small muted mono">${s.id}</span></span></label>`).join('') || '<div class="p-3 small muted">Aucun étudiant actif</div>'; }
ACT['aw-new'] = () => { S.ui.awSel = []; openModal({title:'Attribuer un projet', size:'modal-lg', body:`<form id="awf" data-submit="aw-create" novalidate class="row g-3">
  <div class="col-md-4"><label class="form-label" for="aw-f">Formation</label><select class="form-select" id="aw-f" data-chg="aw-fchg">${FORDER.map(f=>`<option value="${f}">${esc(F[f].name)}</option>`).join('')}</select></div>
  <div class="col-md-8"><label class="form-label" for="aw-t">Titre du projet</label><input class="form-control" id="aw-t" required placeholder="Ex. : Affiche pour un concert"><div class="invalid-feedback">Titre obligatoire.</div></div>
  <div class="col-12"><label class="form-label" for="aw-c">Description et consignes</label><textarea class="form-control" id="aw-c" rows="4" required placeholder="Contexte, ce qui est demandé, formats et fichiers à rendre…"></textarea><div class="invalid-feedback">Décrivez le projet.</div></div>
  <div class="col-md-4"><label class="form-label" for="aw-ty">Type</label><select class="form-select" id="aw-ty"><option>Projet graphique</option><option>Travail pratique</option><option>Exercice</option><option>Livrable</option></select></div>
  <div class="col-md-4"><label class="form-label" for="aw-d">À rendre avant le</label><input class="form-control" type="date" id="aw-d" value="2026-11-05" required></div>
  <div class="col-md-4 d-flex align-items-end"><label class="d-flex gap-2 small mb-2"><input class="form-check-input" type="checkbox" id="aw-ob" checked>Obligatoire pour la certification</label></div>
  <div class="col-12"><span class="form-label d-block">Attribuer à</span><div class="chips mb-2"><button type="button" class="chip-filter on" data-act="aw-mode" data-m="all">Toute la formation</button><button type="button" class="chip-filter" data-act="aw-mode" data-m="sel">Des étudiants précis</button></div><div id="aw-pick" class="cm-pick" hidden><div class="cm-list" id="aw-list">${awListHTML()}</div></div><div class="small muted mt-1" id="aw-count"></div></div></form>`,
  foot:`<button class="btn btn-ghost" data-bs-dismiss="modal">Annuler</button><button class="btn btn-primary" type="submit" form="awf"><i class="fa-solid fa-paper-plane me-1"></i>Attribuer le projet</button>`, onShow: awCount}); S.ui.awMode = 'all'; };
function awCount(){ const f = $('#aw-f')?.value || 'DG', n = S.ui.awMode==='sel' ? (S.ui.awSel||[]).length : awPool(f).length; const c = $('#aw-count'); if (c) c.textContent = `${n} étudiant${n>1?'s':''} recevront ce projet dans leur To-Do, avec une notification.`; }
INP['aw-fchg'] = () => { S.ui.awSel = []; $('#aw-list').innerHTML = awListHTML(); awCount(); };
INP['aw-sel'] = el => { const s = new Set(S.ui.awSel||[]); el.checked ? s.add(el.value) : s.delete(el.value); S.ui.awSel = [...s]; awCount(); };
ACT['aw-mode'] = el => { S.ui.awMode = el.dataset.m; $$('[data-act=aw-mode]').forEach(b=>b.classList.toggle('on', b===el)); $('#aw-pick').hidden = el.dataset.m!=='sel'; awCount(); };
ACT['aw-create'] = () => { const f = $('#aw-f').value, sel = S.ui.awMode==='sel', ids = sel ? (S.ui.awSel||[]) : awPool(f).map(s=>s.id);
  if (!ids.length) { toast('Sélectionnez au moins un étudiant.','warn'); return; }
  const t = $('#aw-t').value, iso = $('#aw-d').value, due = dayOff(iso);
  S.aw.unshift({f, t, type:$('#aw-ty').value, aff: sel ? (ids.length===1 ? 'Individuel · '+S.students.find(s=>s.id===ids[0]).name : `${ids.length} étudiants sélectionnés`) : 'Toute la formation', due:iso.split('-').reverse().join('/'), sub:0, start:0, tot:ids.length, pend:0, ob:$('#aw-ob').checked, ids});
  if (!S.st) loadStudent();
  const toAya = sel ? ids.includes('EVC-26-0142') : fl().includes(f);
  if (toAya && fl().includes(f)) { S.st.todos.unshift({id:'t'+Date.now(), f, t, type:$('#aw-ty').value, due, status:'afaire', mandatory:$('#aw-ob').checked, brief:$('#aw-c').value, files:[], hist:[]});
    S.st.notifs.unshift({id:'n'+Date.now(), cat:'Travaux', f, t:`Nouveau projet : « ${t} ». Lisez les consignes puis cliquez sur « Je démarre ».`, d:"À l'instant", read:false}); }
  audit('Projet attribué', `${t} — ${ids.length} étudiant(s)`); closeModal(); rerender(); toast(`Projet attribué à ${ids.length} étudiant${ids.length>1?'s':''}. Ils le voient dans leur To-Do.`); };
/* Suivi d'un projet : qui a démarré, publié, été validé */
ACT['aw-track'] = el => { const w = S.aw[+el.dataset.i]; const L = (w.ids ? S.students.filter(s=>w.ids.includes(s.id)) : awPool(w.f).slice(0, w.tot));
  const aya = S.st ? S.st.todos.find(x=>x.t===w.t) : null, start = w.start ?? Math.min(w.tot, w.sub+2);
  const stOf = (s, i) => { if (s.id==='EVC-26-0142' && aya) return aya.status==='valide'?['Validé','ok']:aya.status==='soumis'?['Publié · à valider','warn']:aya.status==='afaire'?['Non démarré','mute']:['En cours','info'];
    return i < w.sub ? (i < w.sub - w.pend ? ['Validé','ok'] : ['Publié · à valider','warn']) : i < start ? ['En cours','info'] : ['Non démarré','mute']; };
  const rows = L.map((s,i)=>({s, st:stOf(s,i)}));
  openModal({title:`Suivi — ${esc(w.t)}`, size:'modal-lg', body:`<div class="stats mb-3">${[['Non démarré','mute'],['En cours','info'],['Publié · à valider','warn'],['Validé','ok']].map(([l])=>statBox(l, rows.filter(r=>r.st[0]===l).length)).join('')}</div><div class="panel">${rows.map(r=>`<div class="row-item">${avatar(r.s.name,'sm')}<div class="ri-main"><div class="ri-t small">${esc(r.s.name)}</div><div class="ri-s mono">${r.s.id}</div></div>${pill(r.st[0], r.st[1])}</div>`).join('')}</div>`}); };
/* Notifications de l'administration */
ACT.anotifs = () => { const L = S.anotifs;
  openModal({title:'Notifications', body: L.length ? `<div class="panel">${L.map(n=>`<div class="row-item clickable ${n.read?'':'unread'} ps-4" data-act="anotif-go" data-id="${n.id}"><span class="icon-sq" style="${n.kind==='done'?'--fc:var(--ok);--fcs:var(--ok-soft)':''}"><i class="fa-solid ${n.kind==='done'?'fa-flag-checkered':'fa-play'}"></i></span><div class="ri-main"><div class="small ${n.read?'':'fw-semibold'}" style="white-space:normal">${esc(n.txt)}</div><div class="ri-s">${n.d}</div></div></div>`).join('')}</div>` : empty('Aucune notification'), foot:`<button class="btn btn-ghost" data-act="anotif-all">Tout marquer comme lu</button>`}); };
ACT['anotif-go'] = el => { const n = S.anotifs.find(x=>x.id===el.dataset.id); n.read = true; closeModal(); S.ui.atw = n.kind==='done' ? 'val' : 'tr'; go('a-travaux'); };
ACT['anotif-all'] = () => { S.anotifs.forEach(n=>n.read=true); closeModal(); rerender(); };

/* ----- Studio Creative ----- */
const SC_CRIT = [['Pertinence',30],['Créativité',25],['Technique',25],['Oral',20]];
view('a-studio','admin','Studio Creative','fa-palette', () => { S.sc = S.sc || tStudents().slice(0,7).map((s,i)=>({n:s.name, id:s.id, sub:i!==5, sc:i<4?[15+i%3,14+i%4,16-i%2,13+i]:[null,null,null,null]}));
  const score = r => r.sc.some(v=>v==null) ? null : SC_CRIT.reduce((a,c,i)=>a+r.sc[i]*c[1]/100,0);
  const ranked = S.sc.filter(r=>score(r)!=null).sort((a,b)=>score(b)-score(a));
  return `<div class="row g-3 mb-3"><div class="col-xl-8"><section class="panel c-DG"><div class="panel-h">${pill('Édition 7','acc',1)}<h2>Festival Abidjan Urban Arts</h2><div class="tools"><button class="btn btn-ghost btn-sm" data-act="sc-brief"><i class="fa-solid fa-file-pdf me-1"></i>Brief publié</button>${S.scPub?pill('Résultats publiés','ok'):`<button class="btn btn-primary btn-sm" data-act="sc-pub">Publier les résultats</button>`}</div></div>
    <div class="tbl"><table class="table"><thead><tr><th>Participant</th><th>Création</th>${SC_CRIT.map(c=>`<th class="text-center">${c[0]} <span class="muted">${c[1]} %</span></th>`).join('')}<th class="text-end">Score</th></tr></thead><tbody>${S.sc.map((r,i)=>`<tr><td><b class="small">${esc(r.n)}</b></td><td>${r.sub?'<span class="tag"><i class="fa-solid fa-paperclip"></i>planche.pdf</span>':pill('Non soumis','warn')}</td>${SC_CRIT.map((c,j)=>`<td class="text-center score-cell"><input class="form-control form-control-sm text-center num mx-auto" type="number" min="0" max="20" step="0.5" value="${r.sc[j]??''}" ${r.sub?'':'disabled'} data-chg="sc-score" data-i="${i}" data-j="${j}" aria-label="${c[0]} ${esc(r.n)}"></td>`).join('')}<td class="text-end num"><b>${score(r)!=null?score(r).toFixed(2).replace('.',','):'—'}</b></td></tr>`).join('')}</tbody></table></div></section></div>
    <div class="col-xl-4 d-flex flex-column gap-3">${panel('Classement provisoire', ranked.map((r,i)=>`<div class="row-item"><span class="icon-sq c-DG" style="width:30px;height:30px;font-weight:800">${i+1}</span><div class="ri-main"><div class="ri-t small">${esc(r.n)}</div></div><b class="num">${score(r).toFixed(2).replace('.',',')}</b></div>`).join('')||empty('Aucune note saisie'), {p0:true})}
    ${panel('Jury', ['Marc Yao — Président','Aïssata Bamba — DA, Agence Sankofa','Grace Mensah — Alumni 2026'].map(j=>`<div class="row-item">${avatar(j.split(' — ')[0],'sm')}<div class="ri-main small">${j}</div></div>`).join(''), {p0:true, tools:`<button class="btn btn-ghost btn-sm" data-act="saved" data-m="Invitation jury envoyée.">Inviter</button>`})}</div></div>
  ${panel('Éditions', `<div class="tbl"><table class="table"><thead><tr><th>Édition</th><th>Thème</th><th>Participants</th><th>Lauréat</th><th>Statut</th></tr></thead><tbody>${[[7,'Festival Abidjan Urban Arts',S.sc.length,'—','En cours'],[6,'Campagne Mangez local',22,'Grace Mensah','Archivée'],[5,'Packaging cacao premium',18,'Yann Konan','Archivée']].map(e=>`<tr><td class="mono">#${e[0]}</td><td><b class="small">${e[1]}</b></td><td class="num">${e[2]}</td><td class="small">${e[3]}</td><td>${pill(e[4], e[4]==='En cours'?'info':'mute')}</td></tr>`).join('')}</tbody></table></div>`, {p0:true, tools:`<button class="btn btn-primary btn-sm" data-act="saved" data-m="Édition 8 créée en brouillon.">Nouvelle édition</button>`})}`; });
INP['sc-score'] = el => { S.sc[+el.dataset.i].sc[+el.dataset.j] = el.value===''?null:+el.value; rerender(); };
ACT['sc-pub'] = () => confirmBox('Publier les résultats du Studio Creative', 'Le classement est publié aux participants et les validations sont transmises au module certification.', 'sc-pub-ok');
ACT['sc-pub-ok'] = () => { S.scPub = true; closeModal(); audit('Résultats publiés','Studio Creative édition 7'); rerender(); toast('Résultats publiés et transmis à la certification.'); };
ACT['sc-brief'] = () => openModal({title:'Brief — Studio Creative édition 7', body:`<p>${esc(SEED.studio.theme)}</p><div class="stat-line"><span>Ouverture</span><b>16/10/2026</b></div><div class="stat-line"><span>Clôture des inscriptions</span><b>30/10/2026</b></div><div class="stat-line"><span>Présentation jury</span><b>15/11/2026</b></div>`});

/* ----- RECO 60 ----- */
view('a-reco','admin','RECO 60','fa-hourglass-half', () => { S.rc = S.rc || S.students.filter(s=>(s.f.includes('CM')||s.f.includes('GIA')) && s.status==='Actif').slice(0,10).map((s,i)=>({n:s.name, id:s.id, f:s.f.includes('CM')&&i%2===0?'CM':s.f.includes('GIA')?'GIA':'CM', day:[37,30,44,52,60,18,37,30,60,25][i], step:[3,2,3,3,3,1,3,2,3,2][i], liv:[4,3,5,6,6,1,4,3,6,2][i], st:i===4||i===8?'À valider':i===5?'En retard':'En cours'}));
  return `<div class="grid g-kpi mb-3">${kpi('Campagnes actives','2','CM · Octobre 2026 et GIA · Octobre 2026','fa-flag')}${kpi('Étudiants engagés', S.rc.length, 'projets de 60 jours','fa-users')}${kpi('À valider', S.rc.filter(r=>r.st==='À valider').length, 'jour 60 atteint','fa-circle-check')}${kpi('En retard', S.rc.filter(r=>r.st==='En retard').length, 'livrables manquants','fa-triangle-exclamation')}</div>
  ${panel('Suivi des 60 jours', `<div class="tbl"><table class="table"><thead><tr><th>Étudiant</th><th>Campagne</th><th style="min-width:160px">Avancement</th><th>Étape</th><th class="text-end">Livrables</th><th>Statut</th><th></th></tr></thead><tbody>${S.rc.map((r,i)=>`<tr><td><b class="small">${esc(r.n)}</b><div class="mono small muted">${r.id}</div></td><td>${fchip(r.f)}</td><td>${bar(r.day/60*100,r.f)}<span class="small num muted">Jour ${r.day} / 60</span></td><td class="small">Étape ${r.step} / ${r.f==='CM'?3:5}</td><td class="text-end num">${r.liv} / 6</td><td>${pill(r.st, r.st==='Transmis à la certification'?'ok':r.st==='À valider'?'acc':r.st==='En retard'?'bad':'info')}</td><td class="text-end text-nowrap"><button class="btn btn-ghost btn-sm" data-act="rc-view" data-i="${i}">Livrables</button>${r.st==='À valider'?`<button class="btn btn-ok-soft btn-sm ms-1" data-act="rc-ok" data-i="${i}">Valider</button>`:''}</td></tr>`).join('')}</tbody></table></div>`, {p0:true, tools:`<button class="btn btn-primary btn-sm" data-act="saved" data-m="Campagne RECO 60 créée. Activation automatique au démarrage.">Nouvelle campagne</button>`})}`; });
ACT['rc-view'] = el => { const r = S.rc[+el.dataset.i]; openModal({title:`Livrables RECO 60 — ${esc(r.n)}`, size:'modal-lg', body:`<div class="c-${r.f}">${bar(r.day/60*100,r.f)}<p class="small muted mt-1">Jour ${r.day} / 60 · ${r.liv} livrables déposés</p>${['Fiche identité du projet','Configuration des canaux','Plan d\'action','Journal semaine 1-4','Rapport intermédiaire','Rapport final'].map((l,i)=>`<div class="row-item px-0"><i class="fa-solid ${i<r.liv?'fa-circle-check':'fa-circle'}" style="color:${i<r.liv?'var(--ok)':'var(--line)'}"></i><div class="ri-main small">${l}</div>${i<r.liv?`<button class="btn btn-ghost btn-sm" data-act="fake-dl" data-n="${l}"><i class="fa-solid fa-download"></i></button>`:pill('Attendu','mute')}</div>`).join('')}<label class="form-label mt-3" for="rc-c">Correction / commentaire</label><textarea class="form-control" id="rc-c" rows="2"></textarea><label class="form-label mt-2" for="rc-n">Évaluation (/20)</label><input class="form-control" type="number" id="rc-n" min="0" max="20" style="max-width:120px"></div>`, foot:`<button class="btn btn-primary" data-act="saved" data-m="Évaluation enregistrée.">Enregistrer</button>`}); };
ACT['rc-ok'] = el => { const r = S.rc[+el.dataset.i]; r.st = 'Transmis à la certification'; audit('RECO 60 validé', `${r.n} — ${r.f}`); rerender(); toast(`RECO 60 de ${r.n} validé et transmis au module certification.`); };

/* ----- Finances ----- */
function allTx(){ if (!S.atx) { const modes = ['Orange Money','Wave','MTN MoMo','Espèces','Virement','Carte bancaire','Moov Money']; S.atx = []; S.students.forEach((s,i)=>{ if (s.firstPay) { S.atx.push({...s.firstPay}); return; } let left = s.paid, k = 0; while (left>0 && k<3) { const a = k===2 ? left : Math.min(left, Math.round(s.total*(k?0.25:0.3)/5000)*5000); S.atx.push({d:`${String([6,10+i%8,14+i%7][k]).padStart(2,'0')}/10/2026`, ref:`REC-2026-${String(1100+S.atx.length).padStart(4,'0')}`, s:s.name, sid:s.id, amount:a, mode:modes[(i+k)%7], by: k===1&&i%4===0 ? 'Parent' : 'Étudiant'}); left -= a; k++; } }); S.atx.reverse(); } return S.atx; }
view('a-finances','admin','Finances','fa-wallet', () => { const L = S.students.filter(s=>s.status!=='Archivé'), rec = L.reduce((a,s)=>a+s.paid,0), cre = L.reduce((a,s)=>a+balanceOf(s),0);
  const tab = atabs('afi',[['pay','Paiements'],['tarif','Tarification'],['rec','Recouvrement'],['stat','Statistiques']]);
  const head = `<div class="grid g-kpi mb-3">${kpi('Recettes', `<span class="fs-4">${fcfa(rec)}</span>`, `${allTx().length} transactions`,'fa-arrow-trend-up')}${kpi('Créances', `<span class="fs-4" style="color:var(--bad)">${fcfa(cre)}</span>`, `${L.filter(s=>balanceOf(s)>0).length} étudiants`,'fa-hourglass-half')}${kpi('Taux de recouvrement', fmtPct(rec/(rec+cre)*100), 'sur le facturé','fa-percent')}${kpi('Échéances à 7 jours', '38', fcfa(4350000)+' attendus','fa-calendar-days')}</div>`;
  let b = '';
  if (S.ui.afi==='pay') b = `<div class="toolbar"><div class="grow"><input class="form-control" placeholder="Rechercher une transaction…" data-inp="tx-q" aria-label="Rechercher"></div><button class="btn btn-primary" data-act="tx-new"><i class="fa-solid fa-plus me-1"></i>Enregistrer un paiement</button></div><div id="r-tx">${txRegion()}</div>`;
  if (S.ui.afi==='tarif') b = `<div class="grid g-2">${panel('Tarifs', `<div class="tbl"><table class="table"><thead><tr><th>Formation / profil</th><th class="text-end">Tarif</th><th class="text-end">Acompte</th><th>Solde</th></tr></thead><tbody>${FORDER.map(f=>`<tr><td>${fchip(f)} <b class="small ms-1">${esc(F[f].name)}</b><div class="small muted">${F[f].months} mois</div></td><td class="text-end num">${fcfa(F[f].price)}</td><td class="text-end num">${fcfa(F[f].deposit)}</td><td class="small">${fcfa(F[f].price-F[f].deposit)} le ${F[f].trancheDue}</td></tr>`).join('')}</tbody></table></div>`, {p0:true})}
    ${panel('Remises, bourses et frais', `${[['Bourse Excellence EVC','50 % · 6 bénéficiaires','Active'],['Remise paiement comptant','5 % si solde à l\'inscription','Active'],['Frais de dossier','15 000 FCFA','Active'],['Frais de rattrapage d\'examen','10 000 FCFA','Active'],['Pénalité de retard','5 % après 7 jours','Active']].map(r=>`<div class="row-item px-0"><div class="ri-main"><div class="ri-t small">${r[0]}</div><div class="ri-s">${r[1]}</div></div>${pill(r[2],'ok')}</div>`).join('')}`, {tools:`<button class="btn btn-ghost btn-sm" data-act="saved" data-m="Règle ajoutée.">Ajouter</button>`})}</div>`;
  if (S.ui.afi==='rec') { const due = L.filter(s=>balanceOf(s)>0).map((s,i)=>({...s, late:[0,12,35,4,48,0,9,22][i%8]})).sort((a,b)=>b.late-a.late);
    b = `<div class="alert-strip as-info mb-3"><i class="fa-solid fa-robot"></i>Règles automatiques : relance J-3 et J+1 (WhatsApp + email), pénalité de 5 % à J+7, suspension à J+30, réactivation automatique après régularisation.</div><div class="panel tbl"><table class="table"><thead><tr><th>Étudiant</th><th class="text-end">Solde</th><th class="text-end">Retard</th><th class="text-end">Pénalité</th><th>Statut</th><th class="text-end">Actions</th></tr></thead><tbody>${due.map(s=>`<tr><td><b class="small">${esc(s.name)}</b><div class="small muted">${s.f.join(' + ')} · ${esc(s.phone)}</div></td><td class="text-end num">${fcfa(balanceOf(s))}</td><td class="text-end num">${s.late?`<b style="color:${s.late>30?'var(--bad)':'var(--warn)'}">${s.late} j</b>`:'<span class="muted">à jour</span>'}</td><td class="text-end num">${s.late>7?fcfa(Math.round(balanceOf(s)*0.05/100)*100):'—'}</td><td>${stPill(s.status)}</td><td class="text-end text-nowrap"><button class="btn btn-ghost btn-sm" data-act="relance" data-n="${esc(s.name)}"><i class="fa-solid fa-bell me-1"></i>Relancer</button>${s.status==='Suspendu'?`<button class="btn btn-ok-soft btn-sm ms-1" data-act="as-status-ok" data-id="${s.id}" data-s="Actif">Réactiver</button>`:s.late>30?`<button class="btn btn-danger-soft btn-sm ms-1" data-act="as-status-ok" data-id="${s.id}" data-s="Suspendu">Suspendre</button>`:''}</td></tr>`).join('')}</tbody></table></div>`; }
  if (S.ui.afi==='stat') b = `<div class="grid g-2">${panel('Encaissé et créances par formation', svgBars(FORDER,[{name:'Encaissé',values:FORDER.map(f=>L.filter(s=>s.f.includes(f)).reduce((a,s)=>a+s.paid*F[f].price/s.f.reduce((b,y)=>b+F[y].price,0),0)),color:'var(--ok)'},{name:'Créances',values:FORDER.map(f=>L.filter(s=>s.f.includes(f)).reduce((a,s)=>a+balanceOf(s)*F[f].price/s.f.reduce((b,y)=>b+F[y].price,0),0)),color:'var(--bad)'}],{money:true}))}
    ${panel('Encaissements par session', svgBars(S.sessions.slice(0,3).map(s=>s.name.replace('Session ','')),[{name:'Encaissé',values:S.sessions.slice(0,3).map(se=>L.filter(s=>s.sessionId===se.id).reduce((a,s)=>a+s.paid,0)),color:'var(--accent)'}],{money:true}))}
    ${panel('Modes de paiement', svgDonut(['Orange Money','Wave','MTN MoMo','Espèces','Virement','Carte bancaire','Moov Money'].map((m,i)=>({name:m, value:allTx().filter(t=>t.mode===m).length, color:['#E8620C','#1B6EC2','#E0A800','#5E6479','#2B8A3E','#C2255C','#0B7285'][i]})),{label:allTx().length, sub:'transactions'}))}
    ${panel('Échéances à venir', [['31/10/2026',38,4350000],['30/11/2026',41,4720000],['31/12/2026',40,4600000]].map(e=>`<div class="stat-line py-2 border-bottom"><span>${e[0]} · ${e[1]} étudiants</span><b>${fcfa(e[2])}</b></div>`).join(''))}</div>`;
  return head + tab + b; });
function txRegion(){ const q = (S.ui.txq||'').toLowerCase(), L = allTx().filter(t=>!q || (t.s+t.ref+t.mode).toLowerCase().includes(q)).slice(0,25);
  return `<div class="panel tbl"><table class="table"><thead><tr><th>Date</th><th>Référence</th><th>Étudiant</th><th>Mode</th><th>Payé par</th><th class="text-end">Montant</th></tr></thead><tbody>${L.map(t=>`<tr><td class="num small">${t.d}</td><td class="mono">${t.ref}</td><td class="small"><b>${esc(t.s)}</b></td><td class="small">${t.mode}</td><td class="small">${esc(t.by)}</td><td class="text-end num"><b>${fcfa(t.amount)}</b></td></tr>`).join('')}</tbody></table></div>`; }
INP['tx-q'] = el => { S.ui.txq = el.value; $('#r-tx').innerHTML = txRegion(); };
ACT['tx-new'] = () => openModal({title:'Enregistrer un paiement', body:`<form id="txf" data-submit="tx-create" novalidate class="d-flex flex-column gap-3"><div><label class="form-label" for="tx-s">Étudiant</label><select class="form-select" id="tx-s">${S.students.filter(s=>balanceOf(s)>0).map(s=>`<option value="${s.id}">${esc(s.name)} — solde ${fcfa(balanceOf(s))}</option>`).join('')}</select></div><div><label class="form-label" for="tx-a">Montant (FCFA)</label><input class="form-control num" type="number" id="tx-a" min="500" step="500" value="50000" required></div><div><label class="form-label" for="tx-m">Mode</label><select class="form-select" id="tx-m">${['Espèces','Virement','Orange Money','MTN MoMo','Moov Money','Wave','Carte bancaire'].map(m=>`<option>${m}</option>`).join('')}</select></div><div><label class="form-label" for="tx-b">Payé par</label><input class="form-control" id="tx-b" value="Étudiant"><div class="form-text muted">Indiquez le nom du tiers payeur si besoin (parent, employeur).</div></div></form>`, foot:`<button class="btn btn-primary" type="submit" form="txf">Enregistrer et émettre le reçu</button>`});
ACT['tx-create'] = () => { const s = S.students.find(x=>x.id===$('#tx-s').value), a = Math.min(+$('#tx-a').value, balanceOf(s)), ref = 'REC-2026-' + (1500 + allTx().length); s.paid += a; S.atx.unshift({d:'22/10/2026', ref, s:s.name, sid:s.id, amount:a, mode:$('#tx-m').value, by:$('#tx-b').value}); if (s.status==='Suspendu' && balanceOf(s)===0) s.status='Actif'; audit('Paiement enregistré', `${ref} — ${s.name} — ${fcfa(a)}`); closeModal(); rerender(); toast(`Paiement enregistré. Reçu ${ref} envoyé à ${esc(s.name)}.`); };
ACT['fac-view'] = el => { const s = S.students.find(x=>x.id===el.dataset.id); openModal({title:`Facture FAC-2026-${String(el.dataset.n).padStart(4,'0')}`, body:`<div class="cv-sheet"><div class="d-flex gap-3 align-items-center mb-3">${logoH('couleur','doc-logo')}</div><div class="small mb-2">Facturé à <b>${esc(s.name)}</b> · ${s.id}</div>${s.f.map(f=>`<div class="stat-line"><span>${F[f].name}</span><b>${fcfa(F[f].price)}</b></div>`).join('')}${s.f.length>1?`<div class="stat-line"><span>Remise combinée</span><b>− ${fcfa(s.f.reduce((a,f)=>a+F[f].price,0)-s.total)}</b></div>`:''}<hr><div class="stat-line"><span>Total</span><b>${fcfa(s.total)}</b></div><div class="stat-line"><span>Réglé</span><b>${fcfa(s.paid)}</b></div></div>`, foot:`<button class="btn btn-primary" data-act="fake-dl" data-n="Facture PDF"><i class="fa-solid fa-file-pdf me-1"></i>Exporter en PDF</button>`}); };
ACT.relance = el => toast(`Relance envoyée à ${el.dataset.n} par WhatsApp et email.`,'info');

/* ----- Certifications ----- */
function certEval(s){ return s.f.map(f=>{ const reasons = []; const p = Math.min(100, s.progress + (f==='GIA'?12:f==='CM'?-8:0)); if (p<85) reasons.push(`progression ${p} %`); if (s.presence<75) reasons.push(`présence ${s.presence} %`); if (balanceOf(s)>0) reasons.push('solde non réglé'); return {f, ok:!reasons.length, reasons}; }); }
view('a-certifications','admin','Certifications','fa-award', () => { S.certDone = S.certDone || {};
  const L = S.students.filter(s=>s.status==='Actif' || s.status==='Certifié'), rows = L.flatMap(s=>certEval(s).map(c=>({s, ...c, done: s.status==='Certifié' || S.certDone[s.id+c.f]})));
  const okR = rows.filter(r=>r.ok || r.done), koR = rows.filter(r=>!r.ok && !r.done);
  const tab = atabs('acr',[['ok',`Éligibles (${okR.length})`],['ko',`Non éligibles (${koR.length})`],['crit','Critères'],['jury','Jurys et rattrapages']]);
  let b = '';
  if (S.ui.acr==='ok') b = `<div class="panel tbl"><table class="table"><thead><tr><th>Étudiant</th><th>Formation</th><th>Session</th><th>Décision</th><th class="text-end"></th></tr></thead><tbody>${okR.map(r=>`<tr><td><b class="small">${esc(r.s.name)}</b><div class="mono small muted">${r.s.id}</div></td><td>${fchip(r.f)} <span class="small">${F[r.f].name}</span></td><td class="small">${r.s.session}</td><td>${r.done?pill('Certifié','ok'):pill('Éligible','info')}</td><td class="text-end">${r.done?`<button class="btn btn-ghost btn-sm" data-act="cert-view" data-id="${r.s.id}" data-f="${r.f}"><i class="fa-solid fa-award me-1"></i>Certificat</button>`:`<button class="btn btn-primary btn-sm" data-act="cert-gen" data-id="${r.s.id}" data-f="${r.f}">Valider et générer</button>`}</td></tr>`).join('')||`<tr><td colspan="5">${empty('Aucun étudiant éligible')}</td></tr>`}</tbody></table></div><div class="d-flex justify-content-end mt-3"><button class="btn btn-ghost" data-act="saved" data-m="Résultats publiés sur les espaces étudiants.">Publier les résultats</button></div>`;
  if (S.ui.acr==='ko') b = `<div class="panel tbl"><table class="table"><thead><tr><th>Étudiant</th><th>Formation</th><th>Critères manquants</th><th></th></tr></thead><tbody>${koR.slice(0,20).map(r=>`<tr><td><b class="small">${esc(r.s.name)}</b><div class="mono small muted">${r.s.id}</div></td><td>${fchip(r.f)}</td><td>${r.reasons.map(x=>pill(x,'warn',1)).join(' ')}</td><td class="text-end"><button class="btn btn-ghost btn-sm" data-act="saved" data-m="Étudiant notifié des critères manquants.">Notifier</button></td></tr>`).join('')}</tbody></table></div>`;
  if (S.ui.acr==='crit') b = `<div class="grid g-3">${FORDER.map(f=>panel(`${fchip(f)} <span class="ms-1">${F[f].name}</span>`, ({DG:['Travaux obligatoires validés','Studio Creative validé','Pressbook validé','Rapport de fin de formation','Test final ≥ 10/20','Solde réglé'],CM:['Travaux obligatoires','Évaluations ≥ 10/20','RECO 60 validé','Rapport final','Situation financière'],GIA:['Validation des travaux','Évaluations ≥ 10/20','RECO 60 validé','Situation financière']})[f].map(c=>`<label class="d-flex gap-2 small py-1"><input class="form-check-input" type="checkbox" checked>${c}</label>`).join('') + `<div class="stat-line mt-2"><span>Présence minimale</span><b>75 %</b></div>`)).join('')}</div>`;
  if (S.ui.acr==='jury') b = `<div class="grid g-2">${panel('Jurys programmés', [['DG','Jury final Design Graphic','12/03/2027','Marc Yao, Aïssata Bamba, Jules Ané'],['CM','Jury final Community Management','13/03/2027','Fatim Diabaté, Hervé Kassi, Jules Ané'],['GIA','Jury final GIA','14/03/2027','Koffi Brou, Mariette Aka']].map(j=>`<div class="row-item">${fchip(j[0])}<div class="ri-main"><div class="ri-t small">${j[1]}</div><div class="ri-s">${j[2]} · ${j[3]}</div></div></div>`).join(''), {p0:true})}${panel('Rattrapages', [['Hamed Fofana','GIA','Évaluations','05/11/2026'],['Cédric Gnahoré','DG','Test final','08/11/2026']].map(r=>`<div class="row-item">${avatar(r[0],'sm')}<div class="ri-main"><div class="ri-t small">${r[0]} ${fchip(r[1])}</div><div class="ri-s">${r[2]} · ${r[3]}</div></div>${pill('Programmé','info')}</div>`).join(''), {p0:true})}</div>`;
  return `<div class="grid g-kpi mb-3">${kpi('Dossiers éligibles', okR.filter(r=>!r.done).length,'en attente de validation finale','fa-circle-check')}${kpi('Certificats délivrés', okR.filter(r=>r.done).length,'QR code de vérification','fa-award')}${kpi('Non éligibles', koR.length,'critères à régulariser','fa-hourglass-half')}${kpi('Rattrapages','2','novembre 2026','fa-rotate')}</div>` + tab + b; });
/* Certificat de réussite selon la charte : logo couleur, nom en Space Grotesk, cachet avec le symbole */
const certDoc = ({name, formation, session, mention, code, date='18/10/2026'}) => `<div class="cert">${motif('cert-motif')}<div class="cert-in">
  <div class="d-flex justify-content-between align-items-start gap-3 flex-wrap">${logoH('couleur','cert-logo')}<div class="text-end small"><div class="cert-lbl">N° du certificat</div><b class="mono">${esc(code)}</b></div></div>
  <div class="text-center cert-body"><div class="cert-kicker">Certificat de réussite</div><p class="mb-1">L'École Virtuelle des Créatifs certifie que</p><h2>${esc(name)}</h2><span class="cert-rule"></span><p class="mb-1">a suivi avec succès la formation</p><h3>${esc(formation)}</h3><p class="small mb-0 cert-sub">${esc(session)} · Mention ${esc(mention)} · délivré le ${date}</p></div>
  <div class="cert-foot"><div class="cert-sign"><span class="cert-sig">D. Koné</span><span class="cert-line"></span>Le Directeur de l'EVC</div><div class="cert-seal">${logoSym('couleur')}<small>Cachet de l'EVC</small></div><div class="cert-sign text-end"><div class="cert-qr">${qrSVG(code,64)}</div><span class="cert-line"></span>La Responsable pédagogique</div></div>
</div></div>`;
const certCode = (id,f) => 'EVC-CERT-2026-' + String(Math.abs([...id+f].reduce((a,c)=>a*7+c.charCodeAt(0)|0,3))%9000+1000);
ACT['cert-gen'] = el => { S.certDone[el.dataset.id+el.dataset.f] = true; audit('Certificat généré', `${certCode(el.dataset.id,el.dataset.f)} — ${el.dataset.id} (${el.dataset.f})`); rerender(); ACT['cert-view'](el); toast('Certificat généré et notifié à l\'étudiant.'); };
ACT['cert-view'] = el => { const s = S.students.find(x=>x.id===el.dataset.id), f = el.dataset.f, code = certCode(s.id,f);
  openModal({title:'Certificat', size:'modal-lg', body:certDoc({name:s.name, formation:F[f].name, session:s.session, mention:'Bien', code}), foot:`<a class="btn btn-ghost" href="#verifier" data-act="close-modal">Page de vérification</a><button class="btn btn-primary" data-act="fake-dl" data-n="${code}.pdf"><i class="fa-solid fa-file-pdf me-1"></i>Télécharger</button>`}); };

/* ----- Documents ----- */
view('a-documents','admin','Documents','fa-folder-open', () => { const cats = [...new Set(S.docs.map(d=>d.cat))], c = S.ui.dc||'';
  return `<div class="toolbar"><div class="chips grow"><button class="chip-filter ${!c?'on':''}" data-act="dc" data-c="">Tous</button>${cats.map(x=>`<button class="chip-filter ${c===x?'on':''}" data-act="dc" data-c="${x}">${x}</button>`).join('')}</div><button class="btn btn-primary" data-act="doc-new"><i class="fa-solid fa-upload me-1"></i>Ajouter un document</button></div>
  <div class="panel tbl"><table class="table"><thead><tr><th>Document</th><th>Catégorie</th><th>Formation</th><th>Version</th><th>Mis à jour</th><th>Droits d'accès</th><th></th></tr></thead><tbody>${S.docs.filter(d=>!c||d.cat===c).map((d,i)=>`<tr><td><b class="small">${esc(d.t)}</b></td><td class="small">${d.cat}</td><td>${d.f==='Toutes'?pill('Toutes','mute',1):fchip(d.f)}</td><td class="mono">v${d.v}</td><td class="num small">${d.d}</td><td class="small">${d.acc}</td><td class="text-end text-nowrap"><button class="btn btn-ghost btn-sm" data-act="doc-ver" data-t="${esc(d.t)}" title="Nouvelle version"><i class="fa-solid fa-code-branch"></i></button><button class="btn btn-ghost btn-sm" data-act="doc-acc" data-t="${esc(d.t)}" title="Droits d'accès"><i class="fa-solid fa-lock"></i></button></td></tr>`).join('')}</tbody></table></div>`; });
ACT.dc = el => { S.ui.dc = el.dataset.c; rerender(); };
ACT['doc-new'] = () => openModal({title:'Ajouter un document', body:`<form id="dcf" data-submit="doc-create" novalidate class="d-flex flex-column gap-3"><div><label class="form-label" for="dc-f">Fichier</label><input class="form-control" type="file" id="dc-f" required></div><div><label class="form-label" for="dc-t">Titre</label><input class="form-control" id="dc-t" required></div><div class="row g-2"><div class="col-6"><label class="form-label" for="dc-c">Catégorie</label><select class="form-select" id="dc-c">${['Bibliothèque','Guides','Règlements','Modèles de documents','Rapports','Pressbooks','Certificats','Archives'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="col-6"><label class="form-label" for="dc-fo">Formation</label><select class="form-select" id="dc-fo"><option>Toutes</option>${FORDER.map(f=>`<option>${f}</option>`).join('')}</select></div></div><div><label class="form-label" for="dc-a">Accès</label><select class="form-select" id="dc-a"><option>Étudiants de la formation</option><option>Formateurs</option><option>Administration</option><option>Tous</option></select></div></form>`, foot:`<button class="btn btn-primary" type="submit" form="dcf">Publier</button>`, onShow:()=>$('#dc-f').addEventListener('change',e=>{ if(!$('#dc-t').value) $('#dc-t').value = e.target.files[0]?.name.replace(/\.[^.]+$/,'')||''; })});
ACT['doc-create'] = () => { S.docs.unshift({t:$('#dc-t').value, cat:$('#dc-c').value, f:$('#dc-fo').value, v:'1.0', d:'22/10/2026', acc:$('#dc-a').value}); closeModal(); rerender(); toast('Document publié. Accès appliqué selon les formations.'); };
ACT['doc-ver'] = el => { const d = S.docs.find(x=>x.t===el.dataset.t); if (/^\d/.test(d.v)) { const p = d.v.split('.'); d.v = p[0]+'.'+(+p[1]+1); } d.d = '22/10/2026'; audit('Nouvelle version', `${d.t} v${d.v}`); rerender(); toast(`Version ${d.v} publiée. L'ancienne version reste dans l'historique.`); };
ACT['doc-acc'] = el => { const d = S.docs.find(x=>x.t===el.dataset.t); openModal({title:`Droits d'accès — ${esc(d.t)}`, body:['Étudiants DG','Étudiants CM','Étudiants GIA','Formateurs','Administration','Recruteurs partenaires'].map(r=>`<label class="d-flex gap-2 py-1"><input class="form-check-input" type="checkbox" name="acc" value="${r}" ${d.acc.includes(r.split(' ')[0])||d.acc==='Tous'?'checked':''}>${r}</label>`).join(''), foot:`<button class="btn btn-primary" data-act="doc-acc-ok" data-t="${esc(d.t)}">Enregistrer</button>`}); };
ACT['doc-acc-ok'] = el => { const d = S.docs.find(x=>x.t===el.dataset.t); d.acc = $$('input[name=acc]:checked').map(i=>i.value).join(', ') || 'Administration'; closeModal(); rerender(); toast("Droits d'accès mis à jour."); };

/* ----- Communication ----- */
const AUTOS = [['Confirmation de préinscription',1],['Activation des comptes',1],['Notifications de séances (J-1 et H-1)',1],['Rappels de travaux (J-2)',1],['Notifications de correction',1],["Alertes d'absence",1],['Relances financières (J-3, J+1)',1],['Mise à jour des soldes',1],['Activation des RECO 60',1],["Contrôle d'éligibilité hebdomadaire",1],['Notifications de certification',1],['Suspension automatique (J+30)',0],['Réactivation après régularisation',1]];
/* ----- Communiqués : diffusion instantanée dans l'espace étudiant + email / WhatsApp ----- */
const cmRecipients = () => { const m = S.ui.cmMode||'all', act = S.students.filter(s=>s.status==='Actif');
  if (m==='all') return act;
  if (m==='f') { const fs = S.ui.cmF||[]; return act.filter(s=>s.f.some(f=>fs.includes(f))); }
  if (m==='ses') return S.students.filter(s=>s.sessionId===(S.ui.cmSes||S.sessions[0].id) && s.status!=='Archivé');
  if (m==='debt') return act.filter(s=>balanceOf(s)>0);
  return S.students.filter(s=>(S.ui.cmSel||[]).includes(s.id)); };
function cmRcptHTML(){ const m = S.ui.cmMode||'all', L = cmRecipients(); let extra = '';
  if (m==='f') extra = `<div class="d-flex gap-3 flex-wrap mt-2">${FORDER.map(f=>`<label class="d-flex gap-2 small"><input class="form-check-input" type="checkbox" data-chg="cm-f" value="${f}" ${(S.ui.cmF||[]).includes(f)?'checked':''}>${esc(F[f].name)}</label>`).join('')}</div>`;
  if (m==='ses') extra = `<select class="form-select form-select-sm mt-2" data-chg="cm-ses" aria-label="Session" style="max-width:320px">${S.sessions.map(s=>`<option value="${s.id}" ${(S.ui.cmSes||S.sessions[0].id)===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`;
  if (m==='sel') { const q = norm(S.ui.cmQ||''), list = S.students.filter(s=>s.status!=='Archivé' && (!q || norm(s.name+' '+s.id).includes(q))), sel = S.ui.cmSel||[];
    extra = `<div class="cm-pick mt-2"><div class="d-flex gap-2 p-2 border-bottom"><input class="form-control form-control-sm" placeholder="Rechercher un étudiant…" data-inp="cm-q" value="${esc(S.ui.cmQ||'')}" aria-label="Rechercher un étudiant"><button type="button" class="btn btn-ghost btn-sm text-nowrap" data-act="cm-all">${list.length && list.every(s=>sel.includes(s.id))?'Tout retirer':'Tout cocher'}</button></div><div class="cm-list">${list.map(s=>`<label class="cm-row"><input class="form-check-input" type="checkbox" data-chg="cm-sel" value="${s.id}" ${sel.includes(s.id)?'checked':''}>${avatar(s.name,'sm')}<span class="ri-main"><span class="d-block small fw-semibold">${esc(s.name)}</span><span class="d-block small muted">${s.f.map(fchip).join(' ')} <span class="mono">${s.id}</span></span></span></label>`).join('') || '<div class="p-3 small muted">Aucun étudiant</div>'}</div></div>`; }
  return `<div class="chips">${[['all','Tous les étudiants'],['f','Par formation'],['ses','Par session'],['debt','Solde à régler'],['sel','Sélection nominative']].map(([k,l])=>`<button type="button" class="chip-filter ${m===k?'on':''}" data-act="cm-mode" data-m="${k}">${l}</button>`).join('')}</div>${extra}<div class="small mt-2"><i class="fa-solid fa-users me-1 muted"></i><b>${L.length}</b> destinataire${L.length>1?'s':''}</div>`; }
function cmPaint(focusQ){ const r = $('#cm-rcpt'); if (r) r.innerHTML = cmRcptHTML(); INP['cm-prev'](); if (focusQ) { const i = $('[data-inp=cm-q]'); if (i) { i.focus(); i.setSelectionRange(i.value.length, i.value.length); } } }
view('a-communication','admin','Communiqués','fa-bullhorn', () => { S.autos = S.autos || AUTOS.map(a=>a[1]);
  return `<div class="row g-3"><div class="col-xl-7 d-flex flex-column gap-3">${panel('Nouveau communiqué', `<form data-submit="comm-send" class="d-flex flex-column gap-3" novalidate>
    <div><span class="form-label d-block">Destinataires</span><div id="cm-rcpt">${cmRcptHTML()}</div></div>
    <div><span class="form-label d-block">Diffusion</span><div class="d-flex gap-2 flex-wrap"><label class="ch-opt on" title="Toujours actif"><input class="form-check-input" type="checkbox" checked disabled><i class="fa-solid fa-house-user"></i>Espace étudiant <small>instantané</small></label>${[['Email','fa-solid fa-envelope',true],['WhatsApp','fa-brands fa-whatsapp',true],['SMS','fa-solid fa-comment-sms',false]].map(([c,ic,on])=>`<label class="ch-opt"><input class="form-check-input" type="checkbox" name="cm-ch" value="${c}" ${on?'checked':''} data-chg="cm-prev"><i class="${ic}"></i>${c}</label>`).join('')}</div></div>
    <div class="row g-2"><div class="col-md-5"><label class="form-label" for="cm-ty">Type</label><select class="form-select" id="cm-ty"><option>Communiqué officiel</option><option>Information pédagogique</option><option>Rappel de séance</option><option>Rappel de paiement</option><option>Événement</option></select></div><div class="col-md-7"><label class="form-label" for="cm-t">Objet</label><input class="form-control" id="cm-t" required value="Fermeture exceptionnelle le 1er novembre" data-inp="cm-prev"></div></div>
    <div><label class="form-label" for="cm-b">Message</label><textarea class="form-control" id="cm-b" rows="4" required data-inp="cm-prev">Bonjour {prenom}, l'EVC sera fermée le dimanche 1er novembre (Toussaint). Les séances du week-end sont maintenues en ligne. Bonne journée !</textarea><div class="form-text">Variables : {prenom}, {matricule}, {formation}, {solde}</div></div>
    <label class="d-flex gap-2 small"><input class="form-check-input" type="checkbox" id="cm-imp">Important : afficher en fenêtre à l'ouverture de l'espace étudiant</label>
    <div class="d-flex gap-2 align-items-center flex-wrap"><label class="d-flex gap-2 small"><input class="form-check-input" type="checkbox" id="cm-plan">Programmer l'envoi</label><input class="form-control form-control-sm" type="datetime-local" style="max-width:220px" value="2026-10-27T08:00" aria-label="Date d'envoi"><button class="btn btn-primary ms-auto" type="submit"><i class="fa-solid fa-paper-plane me-1"></i>Envoyer le communiqué</button></div></form>`)}
    ${panel('Communiqués envoyés', S.comms.map((c,i)=>`<div class="row-item clickable" data-act="comm-detail" data-i="${i}"><span class="icon-sq"><i class="fa-solid fa-bullhorn"></i></span><div class="ri-main"><div class="ri-t">${esc(c.t)}</div><div class="ri-s">${c.d} · ${esc(c.target)} · ${c.n} destinataire${c.n>1?'s':''} · ${c.ch.join(', ')}</div></div>${c.plan?pill('Programmé','info'):pill(`Lu ${c.read}`,'ok',1)}<i class="fa-solid fa-chevron-right muted"></i></div>`).join(''), {p0:true})}</div>
  <div class="col-xl-5 d-flex flex-column gap-3">${panel('Aperçu', `<div class="small-caps mb-2">Espace étudiant</div><div class="alert-strip as-info mb-3"><i class="fa-solid fa-bullhorn"></i><span id="cm-pv-app"></span></div><div class="small-caps mb-2">WhatsApp / email</div><div class="rounded p-3" style="background:var(--soft)"><div class="msg" id="cm-preview" style="max-width:100%"></div></div><div class="small muted mt-2" id="cm-cost"></div>`)}
  ${panel('Envois automatiques', AUTOS.map((a,i)=>`<div class="row-item px-0 py-2"><div class="ri-main small">${a[0]}</div><div class="form-check form-switch m-0"><input class="form-check-input" type="checkbox" role="switch" ${S.autos[i]?'checked':''} data-chg="auto" data-i="${i}" aria-label="${a[0]}"></div></div>`).join(''), {sub:'Email, WhatsApp, SMS'})}</div></div>`; }, () => INP['cm-prev']());
INP['cm-prev'] = () => { const p = $('#cm-preview'); if (!p) return; const t = esc($('#cm-t').value), b = esc($('#cm-b').value.replace(/\{prenom\}/g,'Aya').replace(/\{matricule\}/g,'EVC-26-0142').replace(/\{solde\}/g,'255 000 FCFA').replace(/\{formation\}/g,'Infographie & Design Graphique'));
  p.innerHTML = `<b>${t}</b><br>${b}<small>EVC · maintenant</small>`; $('#cm-pv-app').innerHTML = `<b>Communiqué de l'administration</b> · ${t}`;
  const n = cmRecipients().length, ch = $$('input[name=cm-ch]:checked').map(i=>i.value); $('#cm-cost').textContent = `${n} destinataire${n>1?'s':''} · espace étudiant${ch.length?' + '+ch.join(' + '):''}${ch.includes('SMS')?` · coût SMS estimé ${fcfa(n*25)}`:''}`; };
INP.auto = el => { S.autos[+el.dataset.i] = el.checked; toast(`Envoi automatique ${el.checked?'activé':'désactivé'}.`,'info'); };
INP['cm-f'] = () => { S.ui.cmF = $$('[data-chg=cm-f]:checked').map(i=>i.value); cmPaint(); };
INP['cm-ses'] = el => { S.ui.cmSes = el.value; cmPaint(); };
INP['cm-sel'] = el => { const s = new Set(S.ui.cmSel||[]); el.checked ? s.add(el.value) : s.delete(el.value); S.ui.cmSel = [...s]; const sc = $('.cm-list')?.scrollTop; cmPaint(); const l = $('.cm-list'); if (l) l.scrollTop = sc; };
INP['cm-q'] = el => { S.ui.cmQ = el.value; cmPaint(true); };
Object.assign(ACT, {
  'cm-mode': el => { S.ui.cmMode = el.dataset.m; if (el.dataset.m==='f' && !(S.ui.cmF||[]).length) S.ui.cmF = ['DG']; cmPaint(); },
  'cm-all': () => { const q = norm(S.ui.cmQ||''), list = S.students.filter(s=>s.status!=='Archivé' && (!q || norm(s.name+' '+s.id).includes(q))).map(s=>s.id), sel = new Set(S.ui.cmSel||[]); const all = list.every(id=>sel.has(id)); list.forEach(id => all ? sel.delete(id) : sel.add(id)); S.ui.cmSel = [...sel]; cmPaint(); },
  'comm-send': () => { const L = cmRecipients(); if (!L.length) { toast('Choisissez au moins un destinataire.','warn'); return; }
    const t = $('#cm-t').value.trim(), body = $('#cm-b').value.trim(); if (!t || !body) { toast('Renseignez l\'objet et le message.','warn'); return; }
    const ch = ['Espace étudiant', ...$$('input[name=cm-ch]:checked').map(i=>i.value)], imp = $('#cm-imp').checked, plan = $('#cm-plan').checked, m = S.ui.cmMode||'all';
    const target = {all:'Tous les étudiants', f:'Formation : '+(S.ui.cmF||[]).map(f=>F[f].name).join(', '), ses:'Session : '+(S.sessions.find(s=>s.id===(S.ui.cmSes||S.sessions[0].id))||{}).name, debt:'Étudiants avec solde à régler', sel: L.length===1 ? L[0].name : `${L.length} étudiants sélectionnés`}[m];
    S.comms.unshift({id:'c'+Date.now(), d:new Date().toLocaleString('fr-FR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).replace(',',''), t, body, target, ch, n:L.length, read: plan?'—':'0 %', ids:L.map(s=>s.id), plan});
    if (!plan && L.some(s=>s.id==='EVC-26-0142')) { if (!S.st) loadStudent(); const s = S.st.student, txt = body.replace(/\{prenom\}/g,s.first).replace(/\{matricule\}/g,s.matricule).replace(/\{formation\}/g,fl().map(f=>F[f].name).join(', ')).replace(/\{solde\}/g,fcfa(payState().balance));
      S.st.notifs.unshift({id:'n'+Date.now(), cat:'Communiqués', f:null, t, body:txt, ch, imp, comm:true, d:"À l'instant", read:false}); }
    audit(plan?'Communiqué programmé':'Communiqué envoyé', `${t} — ${target} (${L.length})`); rerender();
    toast(plan ? `Communiqué programmé pour ${L.length} étudiant${L.length>1?'s':''}.` : `Communiqué diffusé à ${L.length} étudiant${L.length>1?'s':''} : espace étudiant (instantané)${ch.length>1?' + '+ch.slice(1).join(' + '):''}.`); },
  'comm-detail': el => { const c = S.comms[+el.dataset.i], L = c.ids ? S.students.filter(s=>c.ids.includes(s.id)) : S.students.filter(s=>s.status==='Actif').slice(0, Math.min(c.n, 12));
    const st = (s, k) => { const h = hueOf(s.id+k+c.t); if (c.plan) return pill('Programmé','info'); if (s.id==='EVC-26-0142' && k==='app' && S.st) { const n = S.st.notifs.find(x=>x.comm && x.t===c.t); return n ? pill(n.read?'Lu':'Reçu', n.read?'ok':'info') : pill('Reçu','info'); } return h%5===0 ? pill('Envoyé','mute') : h%2 ? pill(k==='Email'?'Ouvert':'Lu', 'ok') : pill(k==='Email'?'Délivré':'Reçu','info'); };
    openModal({title:esc(c.t), size:'modal-lg', body:`<div class="small muted mb-2">${c.d} · ${esc(c.target)} · ${c.ch.join(', ')}</div>${c.body?`<div class="rounded p-3 mb-3" style="background:var(--soft)">${esc(c.body)}</div>`:''}<div class="tbl"><table class="table"><thead><tr><th>Étudiant</th><th>Espace</th>${c.ch.filter(x=>x!=='Espace étudiant'&&x!=='Notification').map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${L.map(s=>`<tr><td><div class="d-flex align-items-center gap-2">${avatar(s.name,'sm')}<span class="small fw-semibold">${esc(s.name)}</span></div></td><td>${st(s,'app')}</td>${c.ch.filter(x=>x!=='Espace étudiant'&&x!=='Notification').map(x=>`<td>${st(s,x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${c.n>L.length?`<div class="small muted mt-2">… et ${c.n-L.length} autres destinataires.</div>`:''}`}); }
});

