view('a-support','admin','Support','fa-headset', () => { const f = S.ui.tkf||'', L = S.tickets.filter(t=>!f||t.st===f), resp = ['—','Service financier','Responsable pédagogique','Responsable certification','Support technique','Responsable administratif'];
  return `<div class="grid g-kpi mb-3">${kpi('Ouverts', S.tickets.filter(t=>t.st==='Ouvert').length,'non affectés ou non traités','fa-inbox')}${kpi('En cours', S.tickets.filter(t=>t.st==='En cours').length,'','fa-spinner')}${kpi('Délai de 1re réponse','3 h 40','objectif 4 h','fa-clock')}${kpi('Résolus (30 j)','86','satisfaction 4,5 / 5','fa-circle-check')}</div>
  <div class="chips mb-3">${['','Ouvert','En cours','Résolu'].map(x=>`<button class="chip-filter ${f===x?'on':''}" data-act="tkf" data-f="${x}">${x||'Tous'}</button>`).join('')}</div>
  <div class="panel tbl"><table class="table"><thead><tr><th>Ticket</th><th>Demandeur</th><th>Objet</th><th>Catégorie</th><th>Priorité</th><th style="min-width:190px">Affecté à</th><th>Statut</th><th></th></tr></thead><tbody>${L.map(t=>`<tr><td class="mono">${t.id}</td><td class="small"><b>${esc(t.from)}</b><div class="muted">${t.d}</div></td><td class="small">${esc(t.t)}</td><td class="small">${t.cat}</td><td>${pill(t.prio, t.prio==='Critique'||t.prio==='Haute'?'bad':t.prio==='Moyenne'?'warn':'mute',1)}</td><td><select class="form-select form-select-sm" data-chg="tk-to" data-id="${t.id}" aria-label="Affecter">${resp.map(r=>`<option ${r===t.to?'selected':''}>${r}</option>`).join('')}</select></td><td>${pill(t.st, t.st==='Résolu'?'ok':t.st==='En cours'?'info':'acc')}</td><td class="text-end"><button class="btn btn-ghost btn-sm" data-act="tk-reply" data-id="${t.id}">Répondre</button></td></tr>`).join('')}</tbody></table></div>`; });
