ACT['tk-send'] = f => { const t = S.tickets.find(x=>x.id===f.dataset.id); t.st = $('#tk-st').value; if (S.st) { const mine = S.st.tickets.find(x=>x.id===t.id); if (mine) mine.st = t.st; } closeModal(); rerender(); toast(`Réponse envoyée à ${esc(t.from)}.`); };

