view('a-rapports','admin','Rapports et statistiques','fa-chart-line', () => { const type = S.ui.rt || 'pres';
  const types = [['pres','Assiduité par formation'],['fin','Situation financière par session'],['prog','Progression pédagogique par profil'],['ins','Insertion professionnelle']];
  let chart = '', rows = [];
  if (type==='pres') { rows = [['Formation','Présence moyenne','Retards','Absences']].concat(FORDER.map(f=>[F[f].name, `${F[f].presence-3} %`, 18+f.length*4, 9+f.length*2])); chart = svgBars(FORDER,[{name:'Présence %',values:FORDER.map(f=>F[f].presence-3),color:'var(--brand)'}]); }
  if (type==='fin') { rows = [['Session','Facturé','Encaissé','Créances']].concat(S.sessions.slice(0,3).map(se=>{ const L = S.students.filter(s=>s.sessionId===se.id); return [se.name, fcfa(L.reduce((a,s)=>a+s.total,0)), fcfa(L.reduce((a,s)=>a+s.paid,0)), fcfa(L.reduce((a,s)=>a+balanceOf(s),0))]; })); chart = svgBars(S.sessions.slice(0,3).map(s=>s.name.replace('Session ','')),[{name:'Encaissé',values:S.sessions.slice(0,3).map(se=>S.students.filter(s=>s.sessionId===se.id).reduce((a,s)=>a+s.paid,0)),color:'var(--ok)'},{name:'Créances',values:S.sessions.slice(0,3).map(se=>S.students.filter(s=>s.sessionId===se.id).reduce((a,s)=>a+balanceOf(s),0)),color:'var(--bad)'}],{money:true}); }
  if (type==='prog') { rows = [['Profil','Étudiants','Progression moyenne']].concat(PROFILE_KEYS.map(p=>{ const g = S.students.filter(s=>s.profile===p); return [p, g.length, (g.length?Math.round(g.reduce((a,s)=>a+s.progress,0)/g.length):0)+' %']; })); chart = svgBars(PROFILE_KEYS,[{name:'Progression %',values:PROFILE_KEYS.map(p=>{ const g = S.students.filter(s=>s.profile===p); return g.length?Math.round(g.reduce((a,s)=>a+s.progress,0)/g.length):0; }),color:'var(--accent)'}]); }
  if (type==='ins') { rows = [['Promotion','Certifiés','En emploi','En stage','Taux']].concat([['2024',88,49,12,'69 %'],['2025',104,58,15,'70 %'],['Fév. 2026',91,38,18,'62 %']]); chart = svgLine(['2022','2023','2024','2025','2026'],[{name:"Taux d'insertion %",values:[54,61,69,70,62],color:'var(--accent)',area:true}]); }
  S.ui.rrows = rows;
  return `<div class="toolbar"><select class="form-select" style="max-width:320px" data-chg="rt" aria-label="Type de rapport">${types.map(t=>`<option value="${t[0]}" ${type===t[0]?'selected':''}>${t[1]}</option>`).join('')}</select><select class="form-select" style="max-width:200px" aria-label="Période"><option>Octobre 2026</option><option>Trimestre 4 — 2026</option><option>Année 2026</option></select><button class="btn btn-ghost ms-auto" data-act="r-export"><i class="fa-solid fa-file-export me-1"></i>Exporter CSV</button><button class="btn btn-ghost" data-act="fake-dl" data-n="Rapport PDF"><i class="fa-solid fa-file-pdf me-1"></i>PDF</button></div>
  <div class="grid g-2">${panel(types.find(t=>t[0]===type)[1], chart)}${panel('Données', `<div class="tbl"><table class="table"><thead><tr>${rows[0].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.slice(1).map(r=>`<tr>${r.map((c,i)=>`<td class="${i?'num':''}">${typeof c==='string'&&PROFILES[c]?PROFILES[c].f.map(fchip).join(' '):esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`, {p0:true})}</div>`; });
INP.rt = el => { S.ui.rt = el.value; rerender(); };
ACT['r-export'] = () => showCSV('Export du rapport', S.ui.rrows);

/* ----- Rôles et permissions ----- */
view('a-roles','admin','Rôles et permissions','fa-shield-halved', () => `<div class="alert-strip as-info mb-3"><i class="fa-solid fa-circle-info"></i>Cochez les modules accessibles pour chaque rôle. Le menu se met à jour immédiatement : testez avec « Démo » &gt; Rôle administratif.</div>
  <div class="panel tbl"><table class="table perm-table"><thead><tr><th>Module</th>${ADMIN_ROLES.map(r=>`<th style="min-width:96px;white-space:normal;font-size:.64rem">${esc(r)}</th>`).join('')}</tr></thead><tbody>${ADMIN_MODULES.map(m=>`<tr><td class="small"><i class="fa-solid ${m[2]} me-2 muted"></i>${m[1]}</td>${ADMIN_ROLES.map(r=>`<td><input class="form-check-input" type="checkbox" ${S.perms[r].includes(m[0])?'checked':''} ${r==='Super Administrateur'?'disabled':''} data-chg="perm" data-r="${esc(r)}" data-m="${m[0]}" aria-label="${m[1]} pour ${esc(r)}"></td>`).join('')}</tr>`).join('')}<tr style="background:var(--soft)"><td class="small fw-bold"><i class="fa-solid fa-fingerprint me-2" style="color:var(--accent)"></i>MFA obligatoire</td>${ADMIN_ROLES.map(r=>`<td><input class="form-check-input" type="checkbox" ${S.mfa.includes(r)?'checked':''} data-chg="mfa" data-r="${esc(r)}" aria-label="MFA ${esc(r)}"></td>`).join('')}</tr></tbody></table></div>`);
INP.perm = el => { const r = el.dataset.r, m = el.dataset.m; S.perms[r] = el.checked ? [...new Set([...S.perms[r], m])] : S.perms[r].filter(x=>x!==m); audit('Permission modifiée', `${r} : ${ADMIN_MODULES.find(x=>x[0]===m)[1]} ${el.checked?'accordé':'retiré'}`); S.keepScroll = true; route(); toast('Permission mise à jour.'); };
INP.mfa = el => { const r = el.dataset.r; S.mfa = el.checked ? [...S.mfa, r] : S.mfa.filter(x=>x!==r); toast(`MFA ${el.checked?'exigée':'facultative'} pour ${r}.`,'info'); };

/* ----- Journal d'audit ----- */
view('a-audit','admin',"Journal d'audit",'fa-fingerprint', () => `<div class="toolbar"><div class="grow"><input class="form-control" placeholder="Filtrer par utilisateur, action, objet…" data-inp="au-q" aria-label="Filtrer le journal"></div><button class="btn btn-ghost" data-act="au-export"><i class="fa-solid fa-file-export me-1"></i>Exporter</button></div><div id="r-au">${auRegion()}</div>`);
function auRegion(){ const q = (S.ui.auq||'').toLowerCase(); const L = S.audit.filter(a=>!q || Object.values(a).join(' ').toLowerCase().includes(q));
  return `<div class="panel tbl"><table class="table"><thead><tr><th>Horodatage</th><th>Utilisateur</th><th>Rôle</th><th>Action</th><th>Objet</th><th>IP</th></tr></thead><tbody>${L.map(a=>`<tr><td class="mono">${a.d}</td><td class="small"><b>${esc(a.u)}</b></td><td class="small">${esc(a.r)}</td><td>${pill(a.a, a.a.includes('suspendu')||a.a.includes('retir')?'bad':a.a.includes('Paiement')?'ok':'info',1)}</td><td class="small">${esc(a.o)}</td><td class="mono small muted">${a.ip}</td></tr>`).join('')}</tbody></table></div><p class="small muted mt-2">Journal immuable conservé 5 ans. Chaque action de la maquette (validation, paiement, permission…) y est ajoutée en direct.</p>`; }
INP['au-q'] = el => { S.ui.auq = el.value; $('#r-au').innerHTML = auRegion(); };
ACT['au-export'] = () => showCSV("Journal d'audit", [['Horodatage','Utilisateur','Rôle','Action','Objet','IP'], ...S.audit.map(a=>[a.d,a.u,a.r,a.a,a.o,a.ip])]);

/* ----- Paramètres généraux ----- */
view('a-parametres','admin','Paramètres généraux','fa-gear', () => { const tab = atabs('apr',[['id','Identité'],['ped','Règles pédagogiques'],['fin','Règles financières'],['cert','Certificats'],['int','Intégrations'],['sec','Sécurité']]); let b = '';
  const field = (l, v, t='text', id) => `<div class="col-md-6"><label class="form-label" for="${id}">${l}</label><input class="form-control" type="${t}" id="${id}" value="${esc(v)}"></div>`;
  if (S.ui.apr==='id') b = `<form data-submit="params" class="panel panel-b row g-3"><div class="col-12 d-flex gap-3 align-items-center"><span class="brand-mark" style="width:64px;height:64px;font-size:1.4rem;border-radius:16px">evc</span><div><b>Logo</b><div class="small muted">SVG ou PNG transparent, 512 px minimum</div><label class="btn btn-ghost btn-sm mt-1" for="pa-logo">Remplacer</label><input type="file" id="pa-logo" hidden accept="image/*"></div></div>${field('Nom de l\'établissement','École Virtuelle des Créatifs','text','pa-n')}${field('Sigle','EVC','text','pa-s')}${field('Adresse','Cocody Riviera 3, Abidjan','text','pa-a')}${field('Téléphone / WhatsApp','+225 27 22 00 00 00','text','pa-t')}${field('Email','contact@evc.ci','email','pa-e')}${field('Site web','www.evc.ci','text','pa-w')}<div class="col-12 text-end"><button class="btn btn-primary" type="submit">Enregistrer</button></div></form>`;
  if (S.ui.apr==='ped') b = `<form data-submit="params" class="panel panel-b row g-3">${field('Seuil de présence minimal (%)','75','number','pp-1')}${field("Seuil d'alerte d'absentéisme (%)",'80','number','pp-2')}${field('Note minimale de validation (/20)','10','number','pp-3')}${field('Délai de justification d\'absence (heures)','72','number','pp-4')}${field('Durée du RECO 60 (jours)','60','number','pp-5')}${field('Disponibilité des replays (jours)','30','number','pp-6')}<div class="col-12 text-end"><button class="btn btn-primary" type="submit">Enregistrer</button></div></form>`;
  if (S.ui.apr==='fin') b = `<form data-submit="params" class="panel panel-b row g-3">${field('Pénalité de retard (%)','5','number','pf-1')}${field('Délai avant pénalité (jours)','7','number','pf-2')}${field('Suspension après (jours de retard)','30','number','pf-3')}${field('Nombre d\'échéances','4','number','pf-4')}${field('Préfixe des factures','FAC-2026-','text','pf-5')}${field('Préfixe des reçus','REC-2026-','text','pf-6')}<div class="col-12"><label class="d-flex gap-2"><input class="form-check-input" type="checkbox" checked>Réactiver automatiquement après régularisation</label></div><div class="col-12 text-end"><button class="btn btn-primary" type="submit">Enregistrer</button></div></form>`;
  if (S.ui.apr==='cert') b = `<div class="row g-3"><div class="col-lg-5"><form data-submit="params" class="panel panel-b d-flex flex-column gap-3"><div><label class="form-label" for="pc-m">Modèle</label><select class="form-select" id="pc-m"><option>Modèle 2026 — double filet or</option><option>Modèle sobre</option></select></div><div><label class="form-label" for="pc-sg">Signataire</label><input class="form-control" id="pc-sg" value="D. Koné — Directeur Général"></div><div><label class="form-label" for="pc-si">Signature numérisée</label><input class="form-control" type="file" id="pc-si" accept="image/*"></div><div><label class="form-label" for="pc-u">URL de vérification</label><input class="form-control mono" id="pc-u" value="verifier.evc.ci"></div><button class="btn btn-primary" type="submit">Enregistrer</button></form></div><div class="col-lg-7"><div class="cert"><div class="text-center"><div class="small-caps" style="color:#8a6d2b">Aperçu du modèle</div><h2 class="my-2">Prénom Nom</h2><p class="mb-0">Formation · Session · Mention</p></div><div class="d-flex justify-content-between align-items-end mt-4"><div style="font-family:var(--f-display);font-size:1.2rem;color:#14182B">D. Koné</div>${qrSVG('EVC-CERT-MODELE',70)}</div></div></div></div>`;
  if (S.ui.apr==='int') b = `<div class="grid g-3">${[['Orange Money API','Paiements Mobile Money','Connecté'],['MTN MoMo','Paiements Mobile Money','Connecté'],['Wave','Paiements Mobile Money','Connecté'],['Moov Money','Paiements Mobile Money','À configurer'],['Passerelle carte bancaire','Visa / Mastercard','Connecté'],['WhatsApp Business API','Notifications et relances','Connecté'],['Serveur email (SMTP)','Envois transactionnels','Connecté'],['Passerelle SMS','Rappels urgents','Connecté'],['Stockage privé compatible S3','Fichiers, replays, rapports','Connecté'],['Google Workspace','Classes virtuelles Meet','Connecté']].map(i=>`<div class="lib-card"><div class="d-flex justify-content-between align-items-center"><b class="small">${i[0]}</b>${pill(i[2], i[2]==='Connecté'?'ok':'warn')}</div><div class="small muted">${i[1]}</div><button class="btn btn-ghost btn-sm align-self-start" data-act="saved" data-m="${i[2]==='Connecté'?'Connexion testée avec succès.':'Assistant de configuration ouvert.'}">${i[2]==='Connecté'?'Tester':'Configurer'}</button></div>`).join('')}</div>`;
  if (S.ui.apr==='sec') b = `<form data-submit="params" class="panel panel-b row g-3"><div class="col-md-6"><label class="d-flex gap-2"><input class="form-check-input" type="checkbox" checked>HTTPS forcé (HSTS)</label></div><div class="col-md-6"><label class="d-flex gap-2"><input class="form-check-input" type="checkbox" checked>MFA pour les comptes sensibles</label></div><div class="col-md-6"><label class="d-flex gap-2"><input class="form-check-input" type="checkbox" checked>Protection CSRF et XSS (Laravel Sanctum)</label></div><div class="col-md-6"><label class="d-flex gap-2"><input class="form-check-input" type="checkbox" checked>Liens de fichiers signés et expirants</label></div>${field('Expiration de session (minutes)','60','number','ps-1')}${field('Longueur minimale du mot de passe','10','number','ps-2')}${field('Tentatives avant verrouillage','5','number','ps-3')}<div class="col-md-6"><label class="form-label" for="ps-b">Sauvegardes chiffrées</label><select class="form-select" id="ps-b"><option>Quotidienne à 02h00 · rétention 30 jours</option><option>Toutes les 6 heures</option></select></div><div class="col-12 d-flex justify-content-between flex-wrap gap-2"><span class="small muted align-self-center">Dernière sauvegarde : 22/10/2026 02:00 · 4,8 Go · chiffrée AES-256</span><button class="btn btn-primary" type="submit">Enregistrer</button></div></form>`;
  return tab + b; });
ACT.params = () => { audit('Paramètres modifiés', S.ui.apr); toast('Paramètres enregistrés.'); };

/* ----- Validation définitive des travaux déposés ----- */
function validationTab(){ const L = toValidate();
  return `<div class="alert-strip as-info mb-3"><i class="fa-brands fa-whatsapp"></i><span>Les étudiants font corriger leur projet dans la classe virtuelle WhatsApp, puis cliquent sur « Terminer » pour le joindre et le publier ici. Votre validation le rend définitif.</span></div>
  <div class="panel">${L.length ? L.map(x=>`<div class="row-item c-${x.f}">${avatar(x.student,'sm')}<div class="ri-main"><div class="ri-t">${esc(x.t)}</div><div class="ri-s">${fchip(x.f)} ${esc(x.student)} · publié ${esc(x.d).toLowerCase()} · ${x.files.map(f=>`<span class="tag ms-1"><i class="fa-solid fa-paperclip"></i>${esc(f)}</span>`).join('')}</div></div><div class="d-flex gap-2 flex-wrap justify-content-end"><button class="btn btn-danger-soft btn-sm" data-act="av-ko" data-id="${x.id}">À reprendre</button><button class="btn btn-ok-soft btn-sm" data-act="av-ok" data-id="${x.id}"><i class="fa-solid fa-check me-1"></i>Valider</button></div></div>`).join('') : empty('Aucun travail en attente de validation','fa-circle-check')}</div>`; }
function avFind(id){ return toValidate().find(x=>x.id===id); }
Object.assign(ACT, {
  'av-ok': el => { const x = avFind(el.dataset.id);
    if (x.todo) { const t = S.st.todos.find(y=>y.id===x.todo); t.status = 'valide'; t.hist.push({w:'Administration', d:0, c:'Travail validé définitivement.'}); S.st.notifs.unshift({id:'n'+Date.now(),cat:'Travaux',f:t.f,t:`« ${t.t} » est validé définitivement.`,d:"À l'instant",read:false}); }
    else S.av.find(y=>y.id===x.id).st = 'valide';
    audit('Travail validé', `${x.t} — ${x.student} — Validé`); rerender(); toast(`Travail de ${x.student} validé. L'étudiant est notifié.`); },
  'av-ko': el => { const x = avFind(el.dataset.id); openModal({title:`À reprendre — ${esc(x.t)}`, body:`<form id="avk" data-submit="av-ko-ok" data-id="${x.id}" novalidate><label class="form-label" for="avk-m">Motif communiqué à ${esc(x.student)}</label><textarea class="form-control" id="avk-m" rows="3" required placeholder="Ex. : les corrections de la classe virtuelle ne sont pas intégrées, fichier source manquant…"></textarea><div class="invalid-feedback">Indiquez le motif.</div></form>`, foot:`<button class="btn btn-ghost" data-bs-dismiss="modal">Annuler</button><button class="btn btn-danger" type="submit" form="avk">Renvoyer à l'étudiant</button>`}); },
  'av-ko-ok': f => { const x = avFind(f.dataset.id), m = $('#avk-m').value;
    if (x.todo) { const t = S.st.todos.find(y=>y.id===x.todo); t.status = 'reprendre'; t.hist.push({w:'Administration', d:0, c:m}); S.st.notifs.unshift({id:'n'+Date.now(),cat:'Travaux',f:t.f,t:`« ${t.t} » est à reprendre : ${m}`,d:"À l'instant",read:false}); }
    else S.av.find(y=>y.id===x.id).st = 'reprendre';
    audit('Travail à reprendre', `${x.t} — ${x.student} — À reprendre`); closeModal(); rerender(); toast('Travail renvoyé à l\'étudiant avec le motif.','info'); }
});

/* ----- Web TV : publier les cours en vidéo ----- */
view('a-webtv','admin','Web TV','fa-tv', () => { const f = S.ui.wtf || 'DG', q = norm(S.ui.wtq||''), L = S.videos.filter(v=>v.f===f && (!q || norm(v.t+' '+v.mod).includes(q))), all = S.videos.filter(v=>v.pub);
  return `<div class="stats">${statBox('Vidéos publiées', all.length)}${statBox('Heures de cours', Math.round(all.reduce((a,v)=>a+v.dur,0)/60)+' h')}${statBox('Vues ce mois', nfr(all.reduce((a,v)=>a+v.views,0)))}</div>
  <div class="toolbar"><div class="chips">${FORDER.map(x=>`<button class="chip-filter ${f===x?'on':''}" data-act="wt-f" data-f="${x}">${esc(F[x].name)}<span class="n">${S.videos.filter(v=>v.f===x).length}</span></button>`).join('')}</div><div class="ms-auto d-flex gap-2"><input class="form-control form-control-sm" style="width:200px" placeholder="Rechercher…" data-inp="wt-q" value="${esc(S.ui.wtq||'')}" aria-label="Rechercher une vidéo"><button class="btn btn-primary btn-sm" data-act="wt-new"><i class="fa-solid fa-plus me-1"></i>Ajouter une vidéo</button></div></div>
  <div class="panel tbl"><table class="table"><thead><tr><th>Vidéo</th><th>Rubrique</th><th class="text-end">Durée</th><th class="text-end">Vues</th><th>Statut</th><th></th></tr></thead><tbody>${L.map(v=>`<tr><td><div class="d-flex align-items-center gap-2"><span class="icon-sq c-${v.f}" style="width:30px;height:30px"><i class="fa-solid fa-play" style="font-size:.7rem"></i></span><b class="small">${esc(v.t)}</b></div></td><td class="small">${esc(v.mod)}</td><td class="text-end num small">${v.dur} min</td><td class="text-end num small">${v.views}</td><td>${pill(v.pub?'Publiée':'Masquée', v.pub?'ok':'mute')}</td><td class="text-end"><button class="btn btn-ghost btn-sm" data-act="wt-pub" data-id="${v.id}">${v.pub?'Masquer':'Publier'}</button></td></tr>`).join('')}</tbody></table></div>`; });
INP['wt-q'] = el => { S.ui.wtq = el.value; clearTimeout(INP._wtq); INP._wtq = setTimeout(()=>{ rerender(); const i = $('[data-inp=wt-q]'); if (i){ i.focus(); i.setSelectionRange(i.value.length,i.value.length); } }, 250); };
Object.assign(ACT, {
  'wt-f': el => { S.ui.wtf = el.dataset.f; rerender(); },
  'wt-pub': el => { const v = S.videos.find(x=>x.id===el.dataset.id); v.pub = !v.pub; audit(v.pub?'Vidéo publiée':'Vidéo masquée', v.t); rerender(); },
  'wt-new': () => { const f = S.ui.wtf || 'DG'; openModal({title:'Ajouter une vidéo à la Web TV', body:`<form id="wtf" data-submit="wt-save" novalidate class="d-flex flex-column gap-3"><div><label class="form-label" for="wt-fo">Formation</label><select class="form-select" id="wt-fo">${FORDER.map(x=>`<option value="${x}" ${x===f?'selected':''}>${esc(F[x].name)}</option>`).join('')}</select></div><div><label class="form-label" for="wt-mo">Séance</label><select class="form-select" id="wt-mo">${S.formations[f].prog.map(x=>`<option value="${x.n}">Séance ${x.n} — ${esc(x.t)}</option>`).join('')}<option value="0">Bien démarrer (tutoriel)</option></select></div><div><label class="form-label" for="wt-ti">Titre de la vidéo</label><input class="form-control" id="wt-ti" required><div class="invalid-feedback">Titre obligatoire.</div></div><div class="row g-2"><div class="col-8"><label class="form-label" for="wt-url">Lien de la vidéo</label><input class="form-control" id="wt-url" type="url" placeholder="https://…" required><div class="invalid-feedback">Lien valide requis.</div></div><div class="col-4"><label class="form-label" for="wt-du">Durée (min)</label><input class="form-control" type="number" id="wt-du" value="20" min="1"></div></div></form>`, foot:`<button class="btn btn-primary" type="submit" form="wtf">Publier</button>`}); },
  'wt-save': () => { const f = $('#wt-fo').value; const n = +$('#wt-mo').value; S.videos.push({id:'v-new-'+Date.now(), f, mod:n?'Séances':'Bien démarrer', mi:n||-1, n:n||undefined, t:n?`Séance ${n} — ${$('#wt-ti').value}`:$('#wt-ti').value, dur:+$('#wt-du').value||20, p0:0, views:0, pub:true}); if (S.st) S.st.tv.prog[S.videos[S.videos.length-1].id] = 0; S.ui.wtf = f; audit('Vidéo publiée', $('#wt-ti').value); closeModal(); rerender(); toast('Vidéo publiée. Les étudiants la voient dans leur Web TV.'); }
});

/* ----- Créneaux et rendez-vous individuels ----- */
view('a-creneaux','admin','Créneaux et rendez-vous','fa-clock', () => { if (!S.st) loadStudent(); const tab = atabs('acr',[['rdv','Rendez-vous individuels'],['sl','Créneaux de cours']]);
  const me = `${S.st.student.first} ${S.st.student.last}`, req = [...S.st.rdv.filter(r=>r.st!=='Annulé').map(r=>({...r, student:me, mine:true})), ...S.ardv];
  if (S.ui.acr==='rdv') return tab + `<div class="panel">${req.length ? req.map(r=>`<div class="row-item c-${r.f}">${datebox(addDays(r.d), r.f)}<div class="ri-main"><div class="ri-t">${esc(r.student)} · ${esc(r.motif)}</div><div class="ri-s">${fchip(r.f)} ${r.t} · ${esc(r.mode)} · ${esc(F[r.f].trainer)}</div></div>${r.st==='En attente'?`<div class="d-flex gap-2"><button class="btn btn-ghost btn-sm" data-act="ardv" data-id="${r.id}" data-v="Refusé">Refuser</button><button class="btn btn-ok-soft btn-sm" data-act="ardv" data-id="${r.id}" data-v="Confirmé">Confirmer</button></div>`:pill(r.st, r.st==='Confirmé'?'ok':'bad')}</div>`).join('') : empty('Aucune demande','fa-calendar-check')}</div>`;
  return tab + `<div class="d-flex justify-content-end mb-3"><button class="btn btn-primary" data-act="sl-new"><i class="fa-solid fa-plus me-1"></i>Ajouter un créneau</button></div>` + FORDER.map(f=>panel(`${fchip(f)} <span class="ms-1">${esc(F[f].name)}</span>`, S.slots.filter(x=>x.f===f).map(x=>`<div class="row-item"><div class="ri-main"><div class="ri-t">${esc(x.day)} · ${esc(x.h)}</div><div class="ri-s">${esc(x.mode)} · ${esc(x.note)}</div></div><div style="width:140px">${bar(x.taken/x.cap*100,f)}<div class="small muted num text-end">${x.taken} / ${x.cap} inscrits</div></div></div>`).join(''), {p0:true, cls:'mb-3'})).join(''); });
Object.assign(ACT, {
  'ardv': el => { const r = S.st.rdv.find(x=>x.id===el.dataset.id) || S.ardv.find(x=>x.id===el.dataset.id); r.st = el.dataset.v;
    if (S.st.rdv.includes(r)) S.st.notifs.unshift({id:'n'+Date.now(),cat:'Séances',f:r.f,t:`Votre rendez-vous du ${fmtD(addDays(r.d),{day:'numeric',month:'long'})} à ${r.t} est ${r.st.toLowerCase()}.`,d:"À l'instant",read:false});
    audit('Rendez-vous ' + r.st.toLowerCase(), `${r.motif} — ${r.t}`); rerender(); toast(`Rendez-vous ${r.st.toLowerCase()}. L'étudiant est notifié.`); },
  'sl-new': () => openModal({title:'Ajouter un créneau', body:`<form id="slf" data-submit="sl-save" novalidate class="row g-3"><div class="col-12"><label class="form-label" for="sl-f">Formation</label><select class="form-select" id="sl-f">${FORDER.map(x=>`<option value="${x}">${esc(F[x].name)}</option>`).join('')}</select></div><div class="col-6"><label class="form-label" for="sl-d">Jour(s)</label><input class="form-control" id="sl-d" required placeholder="Samedi"></div><div class="col-6"><label class="form-label" for="sl-h">Horaire</label><input class="form-control" id="sl-h" required placeholder="09h00 – 12h00"></div><div class="col-6"><label class="form-label" for="sl-m">Format</label><select class="form-select" id="sl-m"><option>Présentiel</option><option>En ligne</option><option>Hybride</option></select></div><div class="col-6"><label class="form-label" for="sl-c">Places</label><input class="form-control" type="number" id="sl-c" value="15" min="1"></div></form>`, foot:`<button class="btn btn-primary" type="submit" form="slf">Ajouter</button>`}),
  'sl-save': () => { S.slots.push({id:'sl'+Date.now(), f:$('#sl-f').value, day:$('#sl-d').value, h:$('#sl-h').value, mode:$('#sl-m').value, cap:+$('#sl-c').value||15, taken:0, note:'Nouveau créneau'}); closeModal(); rerender(); toast('Créneau ajouté. Les étudiants peuvent le choisir.'); }
});
